public class VolumeDiscount : Rule
{
    public override void Define()
    {
        Order order = default!;
        When().Match<Order>(() => order, o => o.Units > 100 && o.Customer.LoyaltyYears > 2);
        Then().Do(ctx => { order.ApplyDiscount(0.10m); ctx.Update(order); });
    }
}
var repository = new RuleRepository();
repository.Load(x => x.From(typeof(VolumeDiscount)));
var session = repository.Compile().CreateSession();
session.Insert(order);
session.Fire();

